const podcastTitle = originalEvents.title || "Austin Daily Brief";
const hostPersona = "a clear, friendly, and efficient local expert";

// Process and clean extracted content
const processedContent = scrapingResults.map((result, index) => {
  const originalEvent = originalEvents.items[index] || {};

  // Clean and normalize text
  let cleanText = (result.text || '')
    .replace(/\s+/g, ' ')                // Normalize whitespace
    .replace(/[^\w\s.,!?-]/g, '')        // Remove noisy special chars
    .trim();

  // Extract key info with regex
  const dateMatch = cleanText.match(/(\d{1,2}\/\d{1,2}\/\d{4}|\w+\s+\d{1,2},?\s+\d{4}|\w+\s+\d{1,2})/i);
  const timeMatch = cleanText.match(/(\d{1,2}:\d{2}\s*[ap]m|\d{1,2}\s*[ap]m)/i);
  const priceMatch = cleanText.match(/\$\d+|free|admission/i);

  return {
    title: originalEvent.title || "Untitled Event",
    category: originalEvent.category || "General",
    url: originalEvent.url || "",
    content: cleanText.substring(0, 500), // Limit content length
    extracted_date: dateMatch?.[0] || "Date TBD",
    extracted_time: timeMatch?.[0] || "Time TBD",
    extracted_price: priceMatch?.[0] || "Price varies",
    content_quality: cleanText.length > 100 ? "good" : "limited"
  };
});

// Filter for events with good content
const qualityEvents = processedContent.filter(event =>
  event.content_quality === "good" && event.content.length > 50
).slice(0, 4); // Max 4 best events

// Compile final event content for AI
const compiledContent = qualityEvents.map(event =>
  `EVENT: ${event.title}
CATEGORY: ${event.category}
DATE: ${event.extracted_date}
TIME: ${event.extracted_time}
PRICE: ${event.extracted_price}
DETAILS: ${event.content}
---`
).join("\n\n");

// Return dynamic + structured JSON for LLM
return [{
  json: {
    city,
    podcast_title: podcastTitle,
    host_persona: hostPersona,
    events: qualityEvents,
    total_events: processedContent.length,
    compiled_content: compiledContent,
    timestamp: new Date().toISOString()
  }
}];
